import java.io.*;
import java.util.*;

public class COVID {

    private static final int MOD = 998244353;
    private static int[] factorial;

    private static int modPow(int base, long exp) {
        int res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (int) ((res * (long) base) % MOD);
            }
            base = (int) ((base * (long) base) % MOD);
            exp >>= 1;
        }
        return res;
    }

    private static long nCr(int n, int r) {
        long num = factorial[n];
        long den = (factorial[n - r] * (long) factorial[r]) % MOD;
        return (num * modPow((int) den, MOD - 2)) % MOD;
    }

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int n = sc.nextInt();
        long k = sc.nextLong();

        if (k > n - 1) {
            pw.println(0);
            pw.close();
            return;
        }

        factorial = new int[n + 1];
        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (int) ((factorial[i - 1] * (long) i) % MOD);
        }

        int pop = n - (int) k;
        long result = 0;

        for (int i = 0; i <= pop; i++) {
            long term = (nCr(pop, i) * modPow(pop - i, n)) % MOD;
            if (i % 2 == 1) {
                term = (MOD - term) % MOD;
            }
            result = (result + term) % MOD;
        }

        result = (result * nCr(n, pop)) % MOD;
        if (k != 0) {
            result = (result * 2) % MOD;
        }

        pw.println(result);
        pw.close();
    }

    private static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    private static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }

    private static int log(int n, int base) {
        int count = 0;
        while (n >= base) {
            count++;
            n /= base;
        }
        return count;
    }

    private static long square(long x) {
        return x * x;
    }

    static class Pair implements Comparable<Pair> {
        int x, y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Pair other) {
            int cmpX = Integer.compare(this.x, other.x);
            return cmpX != 0 ? cmpX : Integer.compare(this.y, other.y);
        }

        @Override
        public int hashCode() {
            return 31 * x + y;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            Pair pair = (Pair) obj;
            return x == pair.x && y == pair.y;
        }
    }

    static class Scanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public Scanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public Scanner(String path) throws FileNotFoundException {
            reader = new BufferedReader(new FileReader(path));
        }

        public long[] nextLongArray(int size) throws IOException {
            long[] arr = new long[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        public int[] nextIntArray(int size) throws IOException {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine(), " ,");
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }

        public double nextDouble() throws IOException {
            String token = next();
            double value = 0;
            boolean negative = false;
            boolean decimal = false;
            double divisor = 1;

            int start = 0;
            if (token.charAt(0) == '-') {
                negative = true;
                start = 1;
            }

            for (int i = start; i < token.length(); i++) {
                char c = token.charAt(i);
                if (c == '.') {
                    decimal = true;
                } else {
                    value = value * 10 + (c - '0');
                    if (decimal) {
                        divisor *= 10;
                    }
                }
            }

            return (negative ? -1 : 1) * (value / divisor);
        }

        public boolean ready() throws IOException {
            return reader.ready();
        }
    }

    public static void shuffle(int[] arr) {
        Random rand = new Random();
        for (int i = arr.length - 1; i > 0; i--) {
            int j = rand.nextInt(i + 1);
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }
